torio</label><select name="empleado_id" class="input"><option value="0">Externa / manual</option><?php foreach($employees as $employee): ?><option value="<?= (int)$employee['id'] ?>"><?= e($employee['nombre']) ?> · <?= e($employee['documento']) ?></option><?php endforeach; ?></select></div><div><label class="label">Nombre manual</label><input name="nombre" class="input"></div><div><label class="label">Documento</label><input name="documento" class="input"></div><div><label class="label">Vinculación</label><input name="vinculacion" class="input"></div><div class="sm:col-span-2 lg:col-span-3"><label class="label">Declaración / testimonio</label><textarea name="declaracion" class="input min-h-24"></textarea></div><div class="sm:col-span-2 lg:col-span-3 flex justify-end"><button class="btn-secondary" type="submit">Vincular persona</button></div></form></details><?php endif; ?></section>
<section id="investigacion" class="ios-card mt-5 p-5 sm:p-6"><div class="section-heading"><span class="section-icon"><?= icon('search','h-5 w-5') ?></span><div><h2>Investigación y análisis de causas</h2><p>Resolución 1401 de 2007 como referencia metodológica; el contenido debe corresponder al hecho investigado.</p></div></div><form method="post" action="<?= e(url('/eventos/'.$event['id'].'/investigacion')) ?>" class="mt-5"><?= csrf_field() ?><fieldset <?= $investigated?'disabled':'' ?> class="grid gap-4 sm:grid-cols-2"><div><label class="label">Metodología</label><input name="metodologia" class="input" value="<?= e($investigation['metodologia']??'Resolucion 1401 de 2007') ?>"></div><div><label class="label">Fecha de inicio *</label><input type="date" name="fecha_inicio" class="input" required value="<?= e($investigation['fecha_inicio']??'') ?>"></div><div class="sm:col-span-2"><label class="label">Equipo investigador y participación *</label><textarea name="equipo" class="input min-20" required><?= e($investigation['equipo']??'') ?></textarea></div><?php foreach(['causas_inmediatas'=>'Causas inmediatas','causas_basicas'=>'Causas básicas','causas_administrativas'=>'Causas administrativas / del sistema','analisis'=>'Análisis realizado','conclusiones'=>'Conclusiones'] as $field=>$label): ?><div class="<?= $field==='analisis'||$field==='conclusiones'?'sm:col-span-2':'' ?>"><label class="label"><?= $label ?> *</label><textarea name="<?= $field ?>" class="input min-h-24"><?= e($investigation[$field]??'') ?></textarea></div><?php endforeach; ?><?php if(!$investigated): ?><div class="sm:col-span-2 flex justify-end"><button class="btn-primary" type="submit">Guardar borrador e iniciar investigación</button></div><?php endif; ?></fieldset></form><?php if($event['estado']==='En investigacion'): ?><form method="post" action="<?= e(url('/eventos/'.$event['id'].'/investigacion/cerrar')) ?>" class="mt-3 flex justify-end" onsubmit="return confirm('Al cerrar la investigación no podrás editar sus causas ni conclusiones. ¿Continuar?')"><?= csrf_field() ?><button class="btn-secondary" type="submit"><?= icon('lock','h-4 w-4') ?> Cerrar investigación</button></form><?php elseif($investigation&&$investigation['fecha_cierre']): ?><p class="mt-3 text-xs text-emerald-600">Investigación cerrada el <?= format_date($investigation['fecha_cierre']) ?> por <?= e($investigation['elaborado_por_nombre']??'usuario registrado') ?>.</p><?php endif; ?></section>
<section id="acciones" class="ios-card mt-5 p-5 sm:p-6"><div class="section-heading"><span class="section-icon"><?= icon('phva','h-5 w-5') ?></span><div><h2>Acciones derivadas y eficacia</h2><p>Implementar no equivale a ser eficaz: la eficacia requiere medición, fecha, permiso y evidencia revisada.</p></div></div><div class="mt-5 space-y-4"><?php foreach($actions as $action): ?><article class="rounded-2xl bg-slate-50 p-4 ring-1 ring-slate-100"><div class="flex flex-wrap items-start justify-between gap-3"><div><span class="badge <?= status_class($action['estado']) ?>"><?= e($action['estado']) ?></span><span class="badge badge-slate"><?= e($action['tipo']) ?></span><h3 class="mt-2 text-sm font-semibold"><?= e($action['descripcion']) ?></h3><p class="mt-1 text-xs text-slate-500"><?= e($action['responsable']) ?> · Compromiso <?= format_date($action['fecha_compromiso']) ?> · Recursos: <?= e($action['recursos']) ?></p></div><a href="<?= e(url('/evidencias?vinculo='.rawurlencode('evento_accion:'.$action['id']).'#cargar')) ?>" class="btn-secondary"><?= icon('upload','h-4 w-4') ?> Evidencias (<?= (int)$action['evidencias_revisadas'] ?> revisadas)</a></div><?php if(!$closed): ?><form method="post" action="<?= e(url('/eventos/'.$event['id'].'/acciones/'.$action['id'].'/estado')) ?>" class="mt-4 grid items-end gap-3 sm:grid-cols-2 lg:grid-cols-5"><?= csrf_field() ?><div><label class="label">Estado</label><select name="estado" class="input"><?php foreach(['Pendiente','En curso','Implementada','Eficaz','No eficaz','Cancelada'] as $status): ?><option<?= selected($action['estado'],$status) ?>><?= $status ?></option><?php endforeach; ?></select></div><div><label class="label">Fecha de ejecución</label><input type="date" name="fecha_ejecucion" class="input" value="<?= e($action['fecha_ejecucion']) ?>"></div><div><label class="label">Fecha de eficacia</label><input type="date" name="eficacia_fecha" class="input" value="<?= e($action['eficacia_fecha']) ?>"></div><div class="sm:col-span-2"><label class="label">Resultado / justificación</label><input name="eficacia_resultado" class="input" value="<?= e($action['eficacia_resultado']) ?>" placeholder="Resultado medido o justificación de cancelación"></div><div class="lg:col-span-5 flex justify-end"><button class="btn-secondary" type="submit">Actualizar acción</button></div></form><?php elseif($action['eficacia_resultado']): ?><p class="mt-3 text-xs leading-5 text-slate-600"><strong>Resultado:</strong> <?= e($action['eficacia_resultado']) ?></p><?php endif; ?></article><?php endforeach; ?></div><?php if(in_array($event['estado'],['En investigacion','Investigado'],true)): ?><details class="mt-4 rounded-2xl border border-slate-200 p-4"><summary class="cursor-pointer text-xs font-semibold text-blue-600">Programar acción derivada</summary><form method="post" action="<?= e(url('/eventos/'.$event['id'].'/acciones')) ?>" class="mt-4 grid gap-4 sm:grid-cols-2"><?= csrf_field() ?><div><label class="label">Tipo</label><select name="tipo" class="input"><option>Correctiva</option><option>Preventiva</option><option>Mejora</option></select></div><div><label class="label">Fecha compromiso *</label><input type="date" name="fecha_compromiso" class="input" required></div><div class="sm:col-span-2"><label class="label">Acción concreta *</label><textarea name="descripcion" class="input min-h-20" required></textarea></div><div><label class="label">Responsable *</label><input name="responsable" class="input" required></div><div><label class="label">Recursos *</label><input name="recursos" class="input" required></div><div class="sm:col-span-2 flex justify-end"><button class="btn-primary" type="submit">Programar acción</button></div></form></details><?php endif; ?></section>
